"""Regenerate documentation/NODE_LIBRARY.md from the node registry."""

from __future__ import annotations

import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from synapse.nodes.registry import create_registry  # noqa: E402


def main() -> int:
    registry = create_registry()
    groups: dict[str, list] = defaultdict(list)
    for definition in registry.all():
        groups[definition.category].append(definition)

    lines = [
        "# Node catalogue",
        "",
        "Generated by `python scripts/generate_node_docs.py`; do not edit by hand.",
        "",
        "Every node below is executed by the engine and covered by `tests/test_nodes.py`.",
        "Port suffixes: `?` marks an optional input; `[...]` shows an array element type.",
        "",
        f"Total built-in nodes: **{sum(len(v) for v in groups.values())}**",
        "",
    ]
    for category in sorted(groups):
        lines += [f"## {category}", "", "| Node | Type id | Inputs | Outputs |", "| --- | --- | --- | --- |"]
        for d in sorted(groups[category], key=lambda item: item.name):
            inputs = "<br>".join(
                f"{p.name}{'?' if p.optional else ''}: `{p.spec}`" for p in d.inputs
            ) or "—"
            outputs = "<br>".join(f"{p.name}: `{p.spec}`" for p in d.outputs) or "—"
            lines.append(f"| {d.name} | `{d.type_id}` | {inputs} | {outputs} |")
        lines.append("")
    out = ROOT / "documentation" / "NODE_LIBRARY.md"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {out} ({sum(len(v) for v in groups.values())} nodes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
